def minLength(s, numOps):
    n = len(s)

    def cost(m):
        if m == 1:
            c0 = sum(1 for i, ch in enumerate(s) if int(ch) != (i % 2))
            return min(c0, n - c0)
        total = 0
        run = 1
        for i in range(1, n):
            if s[i] == s[i - 1]:
                run += 1
            else:
                total += run // (m + 1)
                run = 1
        total += run // (m + 1)
        return total

    lo, hi = 1, n
    while lo < hi:
        mid = (lo + hi) // 2
        if cost(mid) <= numOps:
            hi = mid
        else:
            lo = mid + 1
    return lo
